  if(me.must_change_password){root.innerHTML=shell(`<section class="ws-card ws-auth"><span class="eyebrow">HUDDL HR · ACCOUNT SETUP</span><h1>Choose your own password.</h1><p>Use your temporary password once, then set a new password to open the HR dashboard.</p><form id="first-password"><label>Temporary password<input name="current_password" type="password" required autocomplete="current-password"></label><label>New password<input name="new_password" type="password" minlength="12" required autocomplete="new-password"></label><button class="button dark">Save password ↗</button></form></section>`,'admin');document.querySelector('#first-password').onsubmit=async e=>{e.preventDefault();try{await action(e.submitter,()=>api('/auth/password','POST',Object.fromEntries(new FormData(e.target))),'Password changed. Your dashboard is ready.');showAdmin()}catch{}};return}
  let metrics,polls,members,display,screens,access;try{[metrics,polls,members,display,screens,access]=await Promise.all([api(`/org/${slug}/metrics`),api(`/org/${slug}/polls`),api(`/org/${slug}/members`),api(`/org/${slug}/display`),api(`/org/${slug}/screens`),api(`/org/${slug}/access`)])}catch(e){root.innerHTML=shell(error(e.message),'admin');return}
