  document.querySelector('.ws-column:last-child').insertAdjacentHTML('beforeend',`<section class="ws-panel"><span class="eyebrow">OFFICE DISPLAYS</span><h2>Screens <small>(${screens.active} / ${screens.screen_limit} active)</small></h2><p class="ws-helper">Open each link on a kitchen, lounge or restroom screen. The link stops working when you deactivate that screen.</p><div class="ws-screen-list">${screens.screens.map(s=>`<form class="ws-screen-row" data-id="${esc(s.id)}"><label>Screen name<input name="name" value="${esc(s.name)}" required></label><label>Location<input name="location" value="${esc(s.location)}" placeholder="e.g. Cairo kitchen"></label><label class="ws-check"><input name="active" type="checkbox" ${s.is_active?'checked':''}> Active</label><div class="ws-screen-actions"><button class="button outline">Save screen</button><a target="_blank" rel="noopener" href="${screenLink(slug,s.token)}">View screen ↗</a><button type="button" class="copy-screen" data-url="${screenLink(slug,s.token)}">Copy link</button></div></form>`).join('')}</div><form id="add-screen"><label>New screen name<input name="name" required placeholder="e.g. Alexandria kitchen"></label><label>Location<input name="location" placeholder="e.g. Floor 2"></label><button class="button dark">+ Add screen</button></form></section>`);
  document.querySelector('.ws-column:last-child').insertAdjacentHTML('afterbegin',`<section class="ws-panel"><span class="eyebrow">EMPLOYEE ACCESS</span><h2>Seats <small>${access.assigned} / ${access.seat_limit} assigned</small></h2><p class="ws-helper">Only emails on this list can join. Employees enter their name and department on first use, then keep their saved profile. No employee email is sent.</p><form id="access-import"><label>Paste employee emails<textarea name="emails" placeholder="salma@company.com&#10;omar@company.com"></textarea></label><label>Or upload a CSV / TXT file<input id="access-file" type="file" accept=".csv,.txt,text/csv,text/plain"></label><button class="button dark">Add employees ↗</button></form><div class="ws-access-list">${access.access.map(a=>`<div class="ws-access-row"><div><strong>${esc(a.email)}</strong><small>${a.joined_at?`${esc(a.display_name)} · ${esc(a.job_title||a.department||'Joined')}`:'Not joined yet'}</small></div><span class="ws-status ${a.is_active?'live':'closed'}">${a.is_active?'Active':'Removed'}</span><button type="button" data-access="${esc(a.id)}" data-active="${a.is_active?'false':'true'}">${a.is_active?'Remove':'Restore'}</button></div>`).join('')||'<p>No employee emails yet.</p>'}</div></section>`);
  const employeeUrl=new URL(link('vote'),location.origin).href;document.querySelector('#access-import').insertAdjacentHTML('beforebegin',`<div class="ws-screen-actions"><a href="${esc(employeeUrl)}" target="_blank" rel="noopener">Employee join link ↗</a><button id="copy-employee-link" type="button" class="copy-screen">Copy link</button></div>`);document.querySelector('#copy-employee-link').onclick=async()=>{try{await navigator.clipboard.writeText(employeeUrl);toast('Employee link copied')}catch{toast('Could not copy link','error')}};
  const screenPanel=document.querySelector('#add-screen').closest('.ws-panel');screenPanel.classList.add('screen-panel');
