  function renderAccess(data){accessPanel.querySelector('h2 small').textContent=`${data.assigned} / ${data.seat_limit} assigned`;accessPanel.querySelector('.ws-access-list').innerHTML=data.access.map(a=>`<div class="ws-access-row"><div><strong>${esc(a.email)}</strong><small>${a.joined_at?`${esc(a.display_name)} · ${esc(a.job_title||a.department||'Joined')}`:'Not joined yet'}</small></div><span class="ws-status ${a.is_active?'live':'closed'}">${a.is_active?'Active':'Removed'}</span><button type="button" data-access="${esc(a.id)}" data-active="${a.is_active?'false':'true'}">${a.is_active?'Remove':'Restore'}</button></div>`).join('')||'<p>No employee emails yet.</p>'}
  function renderScreens(data){screenPanel.querySelector('h2 small').textContent=`(${data.active} / ${data.screen_limit} active)`;screenPanel.querySelector('.ws-screen-list').innerHTML=data.screens.map(s=>`<form class="ws-screen-row" data-id="${esc(s.id)}"><label>Screen name<input name="name" value="${esc(s.name)}" required></label><label>Location<input name="location" value="${esc(s.location)}" placeholder="e.g. Cairo kitchen"></label><label class="ws-check"><input name="active" type="checkbox" ${s.is_active?'checked':''}> Active</label><div class="ws-screen-actions"><button class="button outline">Save screen</button><a target="_blank" rel="noopener" href="${screenLink(slug,s.token)}">View screen ↗</a><button type="button" class="copy-screen" data-url="${screenLink(slug,s.token)}">Copy link</button></div></form>`).join('');const select=screenPanel.querySelector('#screen-choice'),selected=select.value;select.innerHTML=data.screens.filter(s=>s.is_active).map(s=>`<option value="${esc(s.token)}">${esc(s.name)}${s.location?` · ${esc(s.location)}`:''}</option>`).join('');if(data.screens.some(s=>s.is_active&&s.token===selected))select.value=selected;screenPanel.querySelector('#open-selected-screen').disabled=!data.active;screenPanel.querySelector('#add-screen button').disabled=data.active>=data.screen_limit}
  renderScreens(screens);
  document.querySelector('#access-file').onchange=async e=>{const file=e.target.files?.[0];if(!file)return;if(file.size>1000000){toast('Choose a file under 1 MB','error');return}const content=await file.text();document.querySelector('#access-import textarea').value=content;toast(`${extractEmails(content).length} emails found in file`)};
  document.querySelector('#access-import').onsubmit=async e=>{e.preventDefault();const emails=extractEmails(new FormData(e.target).get('emails'));if(!emails.length){toast('Add at least one valid email','error');return}try{await action(e.submitter,()=>api(`/org/${slug}/access`,'POST',{emails}),r=>`${r.added} new seats assigned · ${r.assigned}/${r.seat_limit} in use`);e.target.reset();showAdmin()}catch{}};
